	private Observation execute(String name, boolean legacy, boolean experimental) throws Exception {
		Path storePath = directory.resolve(name);
		Files.createDirectories(storePath);
		if (legacy) {
			Properties properties = new Properties();
			properties.setProperty("version", "2");
			properties.setProperty("triple-indexes", "spoc,posc");
			properties.setProperty("triple-term-indexes", "spoc,cspo");
			try (OutputStream output = Files.newOutputStream(storePath.resolve("store.properties"))) {
				properties.store(output, "legacy format control");
			}
		}

		LmdbStoreConfig config = config(experimental);
		LmdbStore store = new LmdbStore(storePath.toFile(), config);
		store.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory());
		Repository repository = new SailRepository(store);
		repository.init();
		LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
		try {
			Literal upper = VF.createLiteral("same", "EN");
			Literal lower = VF.createLiteral("same", "en");
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:stored-order:left-subject"), LEFT, upper);
				connection.add(VF.createIRI("urn:stored-order:right-subject"), RIGHT, lower);
			}
	
			String plan;
			try (RepositoryConnection connection = repository.getConnection()) {
				TupleQuery tupleQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY);
				plan = tupleQuery.explain(Explanation.Level.Executed).toString();
			}

			List<String> rows = new ArrayList<>();
			try (RepositoryConnection connection = repository.getConnection()) {
				TupleQuery tupleQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY);
				try (var result = tupleQuery.evaluate()) {
					while (result.hasNext()) {
						BindingSet row = result.next();
						rows.add(row.getValue("key").toString());
					}
				}
			}

			try (SailRepositoryConnection connection = (SailRepositoryConnection) repository.getConnection()) {
				List<Value> storedKeys = List.of(storedObject(connection, LEFT), storedObject(connection, RIGHT));
				int comparatorResult = connection.getSailConnection().getComparator()
						.compare(storedKeys.get(0), storedKeys.get(1));
				return new Observation(rows, plan, storedKeys, comparatorResult);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static Value storedObject(RepositoryConnection connection, IRI predicate) {
		try (RepositoryResult<Statement> statements = connection.getStatements(null, predicate, null, false)) {
			if (!statements.hasNext()) {
				throw new AssertionError("Expected a stored value for predicate " + predicate);
			}
			Value value = statements.next().getObject();
			if (statements.hasNext()) {
				throw new AssertionError("Expected one stored value for predicate " + predicate);
			}
			return value;
		}
	}

	private Observation executePredicateJoin(String name, boolean legacy, boolean experimental) throws Exception {
		Path storePath = directory.resolve(name);
		Files.createDirectories(storePath);
		if (legacy) {
			Properties properties = new Properties();
			properties.setProperty("version", "2");
			properties.setProperty("triple-indexes", "spoc,posc");
			properties.setProperty("triple-term-indexes", "spoc,cspo");
			try (OutputStream output = Files.newOutputStream(storePath.resolve("store.properties"))) {
				properties.store(output, "legacy format control");
			}
		}

		LmdbStore store = new LmdbStore(storePath.toFile(), config(experimental));
		store.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory());
		Repository repository = new SailRepository(store);
		repository.init();
		LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
		try {
			IRI firstSplit = VF.createIRI("urn:stored-order:", "shared-predicate");
			IRI equalWithDifferentSplit = VF.createIRI("urn:", "stored-order:shared-predicate");
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:stored-order:subject:first"), firstSplit,
						VF.createLiteral("left"));
				connection.add(VF.createIRI("urn:stored-order:subject:second"), equalWithDifferentSplit,
						VF.createLiteral("right"));
			}

			String plan;
			try (RepositoryConnection connection = repository.getConnection()) {
				TupleQuery tupleQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, PREDICATE_QUERY);
				plan = tupleQuery.explain(Explanation.Level.Executed).toString();
			}

			List<String> rows = new ArrayList<>();
			try (RepositoryConnection connection = repository.getConnection()) {
				TupleQuery tupleQuery = connection.prepareTupleQuery(QueryLanguage.SPARQL, PREDICATE_QUERY);
				try (var result = tupleQuery.evaluate()) {
					while (result.hasNext()) {
						BindingSet row = result.next();
						rows.add(row.getValue("predicate").stringValue());
					}
				}
			}

			try (SailRepositoryConnection connection = (SailRepositoryConnection) repository.getConnection()) {
				List<Value> storedPredicates = new ArrayList<>();
				try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null, false)) {
					while (statements.hasNext()) {
						storedPredicates.add(statements.next().getPredicate());
					}
				}
				int comparatorResult = connection.getSailConnection().getComparator()
						.compare(storedPredicates.get(0), storedPredicates.get(1));
				return new Observation(rows, plan, storedPredicates, comparatorResult);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static List<Value> domainValues() {
		IRI iri = VF.createIRI("urn:stored-order:equal-iri");
		BNode blankNode = VF.createBNode("equal-bnode");
		Literal plain = VF.createLiteral("plain");
		Literal xsdString = VF.createLiteral("plain", XSD.STRING);
		Literal languageUpper = VF.createLiteral("label", "EN-us");
		Literal languageLower = VF.createLiteral("label", "en-US");
		Literal directionalUpper = VF.createLiteral("label", "EN-us", Literal.BaseDirection.RTL);
		Literal directionalLower = VF.createLiteral("label", "en-US", Literal.BaseDirection.RTL);
		Literal directionalLtr = VF.createLiteral("label", "en-US", Literal.BaseDirection.LTR);
		Literal integerOne = VF.createLiteral("1", XSD.INTEGER);
		Literal integerLexicalTie = VF.createLiteral("01", XSD.INTEGER);
		Literal dateTime = VF.createLiteral("2026-11-01T12:37:00Z", XSD.DATETIME);
		Literal dateTimeLexicalTie = VF.createLiteral("2026-11-01T12:37:00.000Z", XSD.DATETIME);
		TripleTerm triple = VF.createTripleTerm(iri, VF.createIRI("urn:stored-order:predicate"), languageUpper);
		TripleTerm equalTriple = VF.createTripleTerm(VF.createIRI("urn:stored-order:equal-iri"),
				VF.createIRI("urn:stored-order:predicate"), languageLower);
		return List.of(iri, VF.createIRI("urn:stored-order:equal-iri"), blankNode, VF.createBNode("equal-bnode"),
				plain, xsdString, languageUpper, languageLower, directionalUpper, directionalLower, directionalLtr,
				integerOne, integerLexicalTie, dateTime, dateTimeLexicalTie, triple, equalTriple);
	}

	private static LmdbStoreConfig config(boolean experimental) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setTripleTermIndexes("spoc,cspo")
				.setAutoGrow(true);
		config.setExperimentalQueryOptimizations(experimental);
		return config;
	}

	private record Observation(List<String> rows, String plan, List<Value> storedKeys, int comparatorResult) {
	}
